static void poly1305_block(poly1305_ctx *ctx, const uint8_t *block) {
    uint64_t c0 = load64_le(block);
    uint64_t c1 = load64_le(block + 8);
    uint64_t h0 = ctx->h[0], h1 = ctx->h[1], h2 = ctx->h[2], h3 = ctx->h[3], h4 = ctx->h[4];
    uint64_t r0 = ctx->r[0], r1 = ctx->r[1], r2 = ctx->r[2], r3 = ctx->r[3], r4 = ctx->r[4];

    // add block
    h0 += c0 & 0x3ffffff;
    h1 += (c0 >> 26) & 0x3ffffff;
    h2 += ((c0 >> 52) | (c1 << 12)) & 0x3ffffff;
    h3 += (c1 >> 14) & 0x3ffffff;
    h4 += (c1 >> 40) & 0x3ffffff;
    h4 += (1 << 24);  // hibit

    // multiply h * r
    uint64_t d0 = h0*r0 + h1*r4*5 + h2*r3*5 + h3*r2*5 + h4*r1*5;
    uint64_t d1 = h0*r1 + h1*r0 + h2*r4*5 + h3*r3*5 + h4*r2*5;
    uint64_t d2 = h0*r2 + h1*r1 + h2*r0 + h3*r4*5 + h4*r3*5;
    uint64_t d3 = h0*r3 + h1*r2 + h2*r1 + h3*r0 + h4*r4*5;
    uint64_t d4 = h0*r4 + h1*r3 + h2*r2 + h3*r1 + h4*r0;

    // carry
    uint64_t c;
    c = d0 >> 26; h0 = d0 & 0x3ffffff; d1 += c;
    c = d1 >> 26; h1 = d1 & 0x3ffffff; d2 += c;
    c = d2 >> 26; h2 = d2 & 0x3ffffff; d3 += c;
    c = d3 >> 26; h3 = d3 & 0x3ffffff; d4 += c;
    c = d4 >> 26; h4 = d4 & 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 = h0 & 0x3ffffff; h1 += c;

    ctx->h[0] = h0; ctx->h[1] = h1; ctx->h[2] = h2; ctx->h[3] = h3; ctx->h[4] = h4;
}
