#include <openssl/evp.h>
#include <openssl/core_names.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>

// parallel chacha20 using EVP
typedef struct {
    const unsigned char *key;
    const unsigned char *nonce; // 12 bytes
    const unsigned char *in;
    unsigned char *out;
    size_t len;
    uint32_t counter;
} chacha_job;

static void* chacha_worker(void *arg) {
    chacha_job *j = (chacha_job*)arg;
    unsigned char nonce16[16];
    memcpy(nonce16, j->nonce, 12);
    nonce16[12] = j->counter & 0xff;
    nonce16[13] = (j->counter >> 8) & 0xff;
    nonce16[14] = (j->counter >> 16) & 0xff;
    nonce16[15] = (j->counter >> 24) & 0xff;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, j->key, nonce16);
    int outl = 0;
    EVP_EncryptUpdate(ctx, j->out, &outl, j->in, (int)j->len);
    EVP_EncryptFinal_ex(ctx, j->out + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

void chacha20_parallel(const unsigned char *key, const unsigned char *nonce,
                       const unsigned char *in, unsigned char *out, size_t len, int nthreads) {
    if (nthreads <= 1 || len < 64*2) {
        chacha_job j = {key, nonce, in, out, len, 1};
        chacha_worker(&j);
        return;
    }
    size_t chunk = len / nthreads;
    // align chunk to 64 bytes
    chunk = (chunk / 64) * 64;
    if (chunk == 0) chunk = 64;
    pthread_t *ths = malloc(sizeof(pthread_t) * nthreads);
    chacha_job *jobs = malloc(sizeof(chacha_job) * nthreads);
    int n = 0;
    size_t pos = 0;
    uint32_t counter = 1;
    while (pos < len) {
        size_t thislen = chunk;
        if (pos + thislen > len) thislen = len - pos;
        jobs[n].key = key; jobs[n].nonce = nonce;
        jobs[n].in = in + pos; jobs[n].out = out + pos;
        jobs[n].len = thislen; jobs[n].counter = counter;
        pthread_create(&ths[n], NULL, chacha_worker, &jobs[n]);
        counter += (uint32_t)(thislen / 64);
        pos += thislen;
        n++;
    }
    for (int i = 0; i < n; i++) pthread_join(ths[i], NULL);
    free(ths); free(jobs);
}

// poly1305 via EVP_MAC
void poly1305_tag(const unsigned char *key, const unsigned char *aad, size_t aad_len,
                  const unsigned char *ct, size_t ct_len, unsigned char *tag) {
    EVP_MAC *mac = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
    OSSL_PARAM params[2];
    params[0] = OSSL_PARAM_construct_utf8_string(OSSL_MAC_PARAM_DIGEST, "NULL", 0);
    params[1] = OSSL_PARAM_construct_end();
    EVP_MAC_init(mctx, key, 32, params);
    EVP_MAC_update(mctx, aad, aad_len);
    EVP_MAC_update(mctx, ct, ct_len);
    // lengths (little endian 64-bit)
    unsigned char lens[16];
    uint64_t al = aad_len, cl = ct_len;
    for (int i = 0; i < 8; i++) { lens[i] = al & 0xff; al >>= 8; }
    for (int i = 0; i < 8; i++) { lens[8+i] = cl & 0xff; cl >>= 8; }
    EVP_MAC_update(mctx, lens, 16);
    size_t outl = 16;
    EVP_MAC_final(mctx, tag, &outl, 16);
    EVP_MAC_CTX_free(mctx);
    EVP_MAC_free(mac);
}

// full AEAD: derive poly key from block 0, parallel chacha20, poly1305
void chacha20poly1305_par(const unsigned char *key, const unsigned char *nonce,
                          const unsigned char *aad, size_t aad_len,
                          const unsigned char *pt, unsigned char *ct, size_t pt_len,
                          unsigned char *tag, int nthreads) {
    // derive poly1305 key from block 0
    unsigned char nonce16[16];
    memcpy(nonce16, nonce, 12);
    nonce16[12] = nonce16[13] = nonce16[14] = nonce16[15] = 0;
    unsigned char polykey[32];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_chacha20(), NULL, key, nonce16);
    int outl = 0;
    unsigned char zeros[32] = {0};
    EVP_EncryptUpdate(ctx, polykey, &outl, zeros, 32);
    EVP_EncryptFinal_ex(ctx, polykey + outl, &outl);
    EVP_CIPHER_CTX_free(ctx);

    // parallel chacha20
    chacha20_parallel(key, nonce, pt, ct, pt_len, nthreads);

    // poly1305
    poly1305_tag(polykey, aad, aad_len, ct, pt_len, tag);
}
EOF
